import json,html
from pathlib import Path

def esc(value): return html.escape(str(value),quote=True)
projects=json.loads(Path('data/projects.json').read_text(encoding='utf-8'))
access=json.loads(Path('data/access.json').read_text(encoding='utf-8'))
def page(title,body,active='home',script=''):
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if name==active else '')+f'>{label}</a>' for url,label,name in [('index.html','首页','home'),('tools.html','工具箱','tools'),('https://linjian-blog.vercel.app/','博客','blog')])
    return f'''<!doctype html>
<html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="ShineLee 的个人入口：博客、在线工具与开源探索。"><meta name="theme-color" content="#f8f9f6"><title>{esc(title)} · ShineLee</title><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='8' fill='%23255d48'/%3E%3Ctext x='12' y='29' fill='white' font-size='28' font-family='Georgia'%3ES%3C/text%3E%3C/svg%3E"><link rel="stylesheet" href="style.css"></head>
<body><a class="skip" href="#main">跳到内容</a><div class="wrap"><header><a class="brand" href="index.html">ShineLee<span>.</span></a><nav aria-label="主导航">{nav}</nav></header><main id="main">{body}</main><footer><span>ShineLee · Where curiosity meets code.</span><span>保持好奇，持续探索。</span></footer></div>{script}</body></html>'''
home='''<section class="hero"><p class="eyebrow">A SMALL CORNER OF THE INTERNET</p><h1>Less noise.<br>More <em>discovery.</em></h1><p class="intro">你好，我是 ShineLee。<br>这里收集我的文字、常用工具，以及关于 AI 与代码的探索。<br>把入口整理好，让注意力回到内容本身。</p><div class="hero-links"><a class="primary" href="https://linjian-blog.vercel.app/">阅读博客 <span aria-hidden="true">↗</span></a><a class="subtle" href="tools.html">打开工具箱 →</a></div></section><section aria-labelledby="entries"><div class="section-head"><h2 id="entries">从这里开始</h2><span>THREE WAYS TO EXPLORE</span></div><div class="entry-grid"><a class="entry" href="https://linjian-blog.vercel.app/"><span class="number">01 / WRITING <span aria-hidden="true">↗</span></span><h3>文字与笔记</h3><p>记录技术实践、开源项目分析，<br>以及值得留下的学习过程。</p><span class="destination">linjian-blog.vercel.app</span></a><a class="entry" href="tools.html"><span class="number">02 / TOOLBOX <span aria-hidden="true">↗</span></span><h3>在线工具箱</h3><p>写作、学习、图片与开发工具，<br>按需打开，随手使用。</p><span class="destination">tools / collections</span></a><a class="entry" href="https://github.com/shinelee2014"><span class="number">03 / OPEN SOURCE <span aria-hidden="true">↗</span></span><h3>开源与探索</h3><p>在 GitHub 上查看项目与代码，<br>从一个想法出发，边做边学。</p><span class="destination">github.com/shinelee2014</span></a></div></section><section class="note"><h2>一点点积累，慢慢生长。</h2><p>不必在每一次探索中找到答案。把有用的工具留下，把实践中的发现写下来。如果你想了解我最近在做什么，可以从<a href="https://linjian-blog.vercel.app/articles">最近的文章</a>开始。</p></section>'''
Path('index.html').write_text(page('个人主页',home),encoding='utf-8')
cards=''.join(f'<article class="tool" data-search="{esc(p["name"]+" "+p["description"])}"><h2>{esc(p["name"])}</h2><p>{esc(p["description"])}</p><div class="tool-links"><a href="{esc(p["url"])}" target="_blank" rel="noopener noreferrer">打开工具 ↗</a><a href="{esc(p["repo"])}" target="_blank" rel="noopener noreferrer">查看仓库</a></div></article>' for p in projects)
tools=f'''<section class="page-head"><p class="eyebrow">THE TOOLBOX</p><h1>工具在手，想法向前。</h1><p>收集已开启 GitHub Pages 的公开项目。保留常用入口，让寻找工具这件事简单一点。</p></section><section class="unlock" id="gate" aria-labelledby="unlock-title"><h2 id="unlock-title">打开我的工具箱</h2><p>使用原有访问密钥继续。</p><form id="unlock-form"><label for="password">访问密钥</label><div class="unlock-controls"><input id="password" type="password" autocomplete="current-password" required><button class="primary" type="submit">解锁 →</button></div><p id="message" class="message" role="status"></p></form><noscript><p>此解锁入口需要启用 JavaScript。</p></noscript></section><section id="directory" hidden><div class="toolbar"><label for="search">筛选<input id="search" type="search" placeholder="搜索工具名称或描述…"></label><span class="count" id="count" role="status">{len(projects)} 个工具</span></div><div class="tools-grid">{cards}</div><p id="empty" class="empty" hidden>没有匹配的工具，试试其他关键词。</p><p class="directory-note">目录随站点一同提供，打开时无需请求 GitHub API。工具本身的可用性由各项目维护。</p></section>'''
script=f'''<script defer src="tools.js" data-digest="{access['digest']}"></script>'''
Path('tools.html').write_text(page('在线工具箱',tools,'tools',script),encoding='utf-8')
Path('overview.html').write_text(page('实验室概览',home),encoding='utf-8')
print(f'Generated three static pages; {len(projects)} public tool entries.')
